#!/usr/bin/env python3
"""Generate Sources/MQ80Core/EmbeddedDefinition.swift from the official VIA JSON."""
import pathlib

repo = pathlib.Path(__file__).resolve().parent.parent
json_path = repo / "definition" / "IQUNIX MQ80 KB-USB.json"
out_path = repo / "Sources" / "MQ80Core" / "EmbeddedDefinition.swift"

text = json_path.read_text(encoding="utf-8")
out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(
    "// Generated by scripts/gen_definition.py from definition/IQUNIX MQ80 KB-USB.json. Do not edit.\n"
    "// Source: official IQUNIX CDN via VIA Guide (vendor asset, personal use).\n"
    "public enum EmbeddedDefinition {\n"
    "    public static let json: String = #\"\"\"\n"
    + text
    + "\n\"\"\"#\n"
    "}\n",
    encoding="utf-8",
)
print(f"wrote {out_path} ({len(text)} bytes of JSON)")
